import bisect
import hashlib

class ConsistentHashRing:
    def __init__(self, vnodes: int = 3, seed: int = 0):
        self.vnodes = vnodes
        self.seed = seed
        self.ring = []  # sorted list of (hash_pos, node_id)

    def _hash(self, token: str) -> int:
        digest = hashlib.sha256(f"{self.seed}:{token}".encode('utf-8')).digest()
        return int.from_bytes(digest[:4], byteorder='big')

    def add_node(self, node_id: str) -> None:
        self.remove_node(node_id)
        for i in range(self.vnodes):
            token = f"{node_id}#vnode{i}"
            pos = self._hash(token)
            bisect.insort(self.ring, (pos, node_id))

    def remove_node(self, node_id: str) -> None:
        self.ring = [(pos, nid) for pos, nid in self.ring if nid != node_id]

    def get_preference_list(self, key: str, r: int) -> list[str]:
        if not self.ring:
            return []

        key_pos = self._hash(key)
        # Find first virtual node with pos >= key_pos
        idx = bisect.bisect_left(self.ring, (key_pos, ""))

        pref_list = []
        seen = set()
        n = len(self.ring)

        for step in range(n):
            curr_idx = (idx + step) % n
            _, nid = self.ring[curr_idx]
            if nid not in seen:
                seen.add(nid)
                pref_list.append(nid)
                if len(pref_list) == r:
                    break

        return pref_list
